using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The MCP SDK discovers tools via [McpServerToolType] on the class
/// and [McpServerTool] on each public method.
/// Constructor parameters are resolved from DI automatically.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _http;

    // The SDK resolves constructor dependencies from the DI container.
    public WeatherTools(HttpClient http)
    {
        _http = http;
    }

    [McpServerTool, Description("Get current weather for a city")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'Seattle'")] string city)
    {
        var response = await _http.GetAsync($"/weather?city={Uri.EscapeDataString(city)}");
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync();
        return json;
    }

    [McpServerTool, Description("Get 5-day forecast for a city")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Temperature unit: 'celsius' or 'fahrenheit'")] string units = "celsius")
    {
        var response = await _http.GetAsync(
            $"/forecast?city={Uri.EscapeDataString(city)}&units={units}");
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }
}

using Microsoft.Extensions.DependencyInjection;
using ModelContextProtocol.Server;
using McpServer;

var builder = McpServerBuilder.CreateDefault(args);

builder.ServerInfo = new() { Name = "weather-mcp", Version = "1.0.0" };

// Register an HttpClient for WeatherTools via the typed-client pattern.
// DI will inject this HttpClient into the WeatherTools constructor.
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.BaseAddress = new Uri("https://api.example.com");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

// Discover and register all [McpServerToolType] classes in this assembly.
builder.WithTools<WeatherTools>();

// Build and run with stdio transport (reads JSON-RPC from stdin, writes to stdout).
await using var server = builder.Build();
await server.RunAsync();

